  for i in [0..mother_facts_p.length) { if mother_facts_p[i] < 1 { mother_facts_h[i] = flip(mother_facts_p[i]); } else { mother_facts_h[i] = true; } }
  // father/2: 1 facts
  father_facts_1 := [1000000]: ℤ[];
  father_facts_2 := [1000004]: ℤ[];
  father_facts_p := [1.0]: ℝ[];
  father_facts_h := array(father_facts_p.length, false);
  for i in [0..father_facts_p.length) { if father_facts_p[i] < 1 { father_facts_h[i] = flip(father_facts_p[i]); } else { father_facts_h[i] = true; } }
  // cg/3: 4 facts
  cg_facts_1 := [1000001, 1000001, 1000000, 1000000]: ℤ[];
  cg_facts_2 := [1, 2, 1, 2]: ℤ[];
  cg_facts_3 := [1000002, 1000005, 1000005, 1000002]: ℤ[];
  cg_facts_p := [1.0, 1.0, 1.0, 1.0]: ℝ[];
  cg_facts_h := array(cg_facts_p.length, false);
  for i in [0..cg_facts_p.length) { if cg_facts_p[i] < 1 { cg_facts_h[i] = flip(cg_facts_p[i]); } else { cg_facts_h[i] = true; } }

