  father_2 := father_facts_2;
  father_h := father_facts_h;

  mother_1 := mother_facts_1;
  mother_2 := mother_facts_2;
  mother_h := mother_facts_h;

  // cg/3: recursive; the rules applied in stages from no tuple,
  // each reading the stage before, until a stage adds no tuple and the stages number the tuples
  // the draws of `0.5::cg(X,1,A); 0.5::cg(X,1,B) :- mother(Y,X), cg(Y,1,A), cg(Y,2,B).`, by instance
  coins3_1 := []: ℤ[];
  coins3_2 := []: ℤ[];
  coins3_3 := []: ℤ[];
  coins3_4 := []: ℤ[];
  coins3_c := []: ℕ[];
  // the draws of `0.5::cg(X,2,A); 0.5::cg(X,2,B) :- father(Y,X), cg(Y,1,A), cg(Y,2,B).`, by instance
  coins4_1 := []: ℤ[];
  coins4_2 := []: ℤ[];
  coins4_3 := []: ℤ[];
  coins4_4 := []: ℤ[];
  coins4_c := []: ℕ[];
  cg_1 := []: ℤ[];
  cg_2 := []: ℤ[];
  cg_3 := []: ℤ[];
  cg_h := []: 𝔹[];
  stage1 := 0;
  before2 := -1;
  while stage1 < cg_h.length || cg_h.length != before2 {
    before2 = cg_h.length;
    next_cg_1 := cg_facts_1;
    next_cg_2 := cg_facts_2;
    next_cg_3 := cg_facts_3;
    next_cg_h := cg_facts_h;
    // 0.5::cg(X,1,A); 0.5::cg(X,1,B) :- mother(Y,X), cg(Y,1,A), cg(Y,2,B).
    for k3 in [0..mother_h.length) {
      Y := mother_1[k3];
      X := mother_2[k3];
      x4 := mother_h[k3];
      for k5 in [0..cg_h.length) {
        if cg_1[k5] == Y && cg_2[k5] == 1 {
          A := cg_3[k5];
          x6 := cg_h[k5];
          for k7 in [0..cg_h.length) {
            if cg_1[k7] == Y && cg_2[k7] == 2 {
              B := cg_3[k7];
              x8 := cg_h[k7];
              c9 := 0;
              g10 := false;
              for k11 in [0..coins3_c.length) { if coins3_1[k11] == X && coins3_2[k11] == A && coins3_3[k11] == B && coins3_4[k11] == Y { c9 = coins3_c[k11]; g10 = true; } }
              if !g10 { c9 = categorical([0.5, 0.5]); coins3_1 = coins3_1 ~ [X]; coins3_2 = coins3_2 ~ [A]; coins3_3 = coins3_3 ~ [B]; coins3_4 = coins3_4 ~ [Y]; coins3_c = coins3_c ~ [c9]; }
