// cplint_light.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // push/0: 1 facts
  push_facts_p := [1.0]: ℝ[];
  push_facts_h := array(push_facts_p.length, false);
  for i in [0..push_facts_p.length) { if push_facts_p[i] < 1 { push_facts_h[i] = flip(push_facts_p[i]); } else { push_facts_h[i] = true; } }

  push_h := push_facts_h;

  light_h := []: 𝔹[];
  // 0.4::light :- push.
  for k1 in [0..push_h.length) {
    x2 := push_h[k1];
    c3 := flip(0.4);
    v4 := x2 && c3;
    f5 := false;
    for k6 in [0..light_h.length) {
      if true { light_h[k6] = light_h[k6] || v4; f5 = true; }
    }
    if !f5 { light_h = light_h ~ [v4]; }
  }

  replace_h := []: 𝔹[];
  // replace :- \+ light.
  n7 := false;
  for k8 in [0..light_h.length) { if true { n7 = n7 || light_h[k8]; } }
  v9 := !n7;
  f10 := false;
  for k11 in [0..replace_h.length) {
    if true { replace_h[k11] = replace_h[k11] || v9; f10 = true; }
  }
  if !f10 { replace_h = replace_h ~ [v9]; }

  q12 := false;
  for q12_k in [0..replace_h.length) { if true { q12 = replace_h[q12_k]; } }
  q13 := false;
  for q13_k in [0..light_h.length) { if true { q13 = light_h[q13_k]; } }
  queries := [q12, q13];
  return queries[1];
}

