// cplint_eruption.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // the symbols as numbers: east_west 1000000, southwest_northeast 1000001
  // sudden_energy_release/0: 1 facts
  sudden_energy_release_facts_p := [0.7]: ℝ[];
  sudden_energy_release_facts_h := array(sudden_energy_release_facts_p.length, false);
  for i in [0..sudden_energy_release_facts_p.length) { if sudden_energy_release_facts_p[i] < 1 { sudden_energy_release_facts_h[i] = flip(sudden_energy_release_facts_p[i]); } else { sudden_energy_release_facts_h[i] = true; } }
  // fault_rupture/1: 2 facts
  fault_rupture_facts_1 := [1000001, 1000000]: ℤ[];
  fault_rupture_facts_p := [1.0, 1.0]: ℝ[];
  fault_rupture_facts_h := array(fault_rupture_facts_p.length, false);
  for i in [0..fault_rupture_facts_p.length) { if fault_rupture_facts_p[i] < 1 { fault_rupture_facts_h[i] = flip(fault_rupture_facts_p[i]); } else { fault_rupture_facts_h[i] = true; } }

  fault_rupture_1 := fault_rupture_facts_1;
  fault_rupture_h := fault_rupture_facts_h;

  sudden_energy_release_h := sudden_energy_release_facts_h;

  earthquake_h := []: 𝔹[];
  eruption_h := []: 𝔹[];
  // 0.6::eruption; 0.3::earthquake :- sudden_energy_release, fault_rupture(_A1).
  for k1 in [0..sudden_energy_release_h.length) {
    x2 := sudden_energy_release_h[k1];
    for k3 in [0..fault_rupture_h.length) {
      _A1 := fault_rupture_1[k3];
      x4 := fault_rupture_h[k3];
      c5 := categorical([0.6, 0.3, 1 - 0.6 - 0.3]);
      v6 := x2 && x4 && c5 == 0;
      f7 := false;
      for k8 in [0..eruption_h.length) {
        if true { eruption_h[k8] = eruption_h[k8] || v6; f7 = true; }
      }
      if !f7 { eruption_h = eruption_h ~ [v6]; }
      v9 := x2 && x4 && c5 == 1;
      f10 := false;
      for k11 in [0..earthquake_h.length) {
        if true { earthquake_h[k11] = earthquake_h[k11] || v9; f10 = true; }
      }
      if !f10 { earthquake_h = earthquake_h ~ [v9]; }
    }
  }

  q12 := false;
  for q12_k in [0..eruption_h.length) { if true { q12 = eruption_h[q12_k]; } }
  q13 := false;
  for q13_k in [0..earthquake_h.length) { if true { q13 = earthquake_h[q13_k]; } }
  queries := [q12, q13];
  return queries[1];
}

