// cplint_mendelc.pl: a ProbLog program written in WebPPL by tddlog's
// scripts/problog2ppl.py, first order as it is written. A relation is an
// object from a tuple's key to {t: the tuple, v: whether it holds}, v a
// function of no arguments that says whether the tuple holds in the world
// being enumerated, memoized within it; each probabilistic fact is a coin of
// its own (`flip`), drawn where a world first reads it; a rule's instances
// are maps over the relations its body joins. The facts are lpFacts, which
// the runner reads from the facts file: {relation: [[argument ...,
// probability], ...]}. The queries are enumerated exactly, given the
// evidence.

var yes = function() { return true; };
var no = function() { return false; };
// a coin of probability p, drawn once in a world
var coin = function(p) { return mem(function() { return flip(p); }); };
var and = function(xs) { return function() { return all(function(x) { return x(); }, xs); }; };
var not = function(x) { return function() { return !x(); }; };
var keyOf = function(t) { return JSON.stringify(t); };
// whether the tuple t of r holds
var holds = function(r, t) { var e = r[keyOf(t)]; return e ? e.v : no; };
// the entry of t, if it is a tuple of r: none or one to map over
var probe = function(r, t) { var e = r[keyOf(t)]; return e ? [e] : []; };
// the entries of r by their values at positions ps (from 0)
var index = function(r, ps) {
  return _.groupBy(map(function(e) { return {k: keyOf(_.at(e.t, ps)), t: e.t, v: e.v}; }, _.values(r)), 'k');
};
// whether a tuple of the index's key k holds
var holdsAny = function(ix, k) {
  var es = ix[keyOf(k)] || [];
  return function() { return any(function(e) { return e.v(); }, es); };
};
// the choice of an annotated disjunction p1::h1; ...; pn::hn: whether each
// head is the one chosen, the k-th with probability pk and none with the rest
var choose = function(ps) {
  var rest = 1 - sum(ps);
  var vs = _.range(ps.length + (rest > 0 ? 1 : 0));
  var c = mem(function() { return categorical({ps: rest > 0 ? ps.concat([rest]) : ps, vs: vs}); });
  return map(function(k) { return function() { return c() === k; }; }, _.range(ps.length));
};
// the instances, [relation, tuple, holding] each, of relation `name`
var only = function(name, instances) { return filter(function(i) { return i[0] === name; }, instances); };
// the relation of base and instances: a tuple holds where its fact or one
// of its instances does
var relation = function(base, instances) {
  var entries = map(function(e) { return {k: keyOf(e.t), t: e.t, v: e.v}; }, _.values(base)).concat(
    map(function(i) { return {k: keyOf(i[1]), t: i[1], v: i[2]}; }, instances));
  return mapObject(function(k, es) {
    var vs = map(function(e) { return e.v; }, es);
    return {t: es[0].t, v: mem(function() { return any(function(x) { return x(); }, vs); })};
  }, _.groupBy(entries, 'k'));
};
// a relation of facts, [argument ..., probability] each
var relationOfFacts = function(rows) {
  return _.fromPairs(map(function(row) {
    var t = row.slice(0, row.length - 1), p = row[row.length - 1];
    return [keyOf(t), {t: t, v: p >= 1 ? yes : coin(p)}];
  }, rows));
};

var mother_facts = relationOfFacts(lpFacts['mother/2'] || []);
var father_facts = relationOfFacts(lpFacts['father/2'] || []);
var cg_facts = relationOfFacts(lpFacts['cg/3'] || []);

var father = father_facts;

var mother = mother_facts;

// cg/3: recursive; the rules applied in stages from no tuple, each
// reading the stage before, until a stage adds no tuple and the stages number the tuples
var coins3 = mem(function(instance) { return choose([0.5, 0.5]); });   // by instance, of `0.5::cg(X,1,A); 0.5::cg(X,1,B) :- mother(Y,X), cg(Y,1,A), cg(Y,2,B).`
var coins4 = mem(function(instance) { return choose([0.5, 0.5]); });   // by instance, of `0.5::cg(X,2,A); 0.5::cg(X,2,B) :- father(Y,X), cg(Y,1,A), cg(Y,2,B).`
var stage_cg = function(rels) {
  var cg = rels[0];
  var cg_by_1_2 = index(cg, [0, 1]);
  var instances_cg = [].concat(
    // 0.5::cg(X,1,A); 0.5::cg(X,1,B) :- mother(Y,X), cg(Y,1,A), cg(Y,2,B).
    (function() {
      return _.flatten(map(function(e1) {
        var Y = e1.t[0];
        var X = e1.t[1];
        return _.flatten(map(function(e2) {
          var A = e2.t[2];
          return _.flatten(map(function(e3) {
            var B = e3.t[2];
            var chosen = coins3([X, A, B, Y]);
            return [
              ['cg', [X, 1, A], and([e1.v, e2.v, e3.v, chosen[0]])],
              ['cg', [X, 1, B], and([e1.v, e2.v, e3.v, chosen[1]])]
            ];
          }, (cg_by_1_2[keyOf([Y, 2])] || [])));
        }, (cg_by_1_2[keyOf([Y, 1])] || [])));
      }, _.values(mother)));
    })(),
    // 0.5::cg(X,2,A); 0.5::cg(X,2,B) :- father(Y,X), cg(Y,1,A), cg(Y,2,B).
    (function() {
      return _.flatten(map(function(e1) {
        var Y = e1.t[0];
        var X = e1.t[1];
        return _.flatten(map(function(e2) {
          var A = e2.t[2];
          return _.flatten(map(function(e3) {
            var B = e3.t[2];
            var chosen = coins4([X, A, B, Y]);
            return [
              ['cg', [X, 2, A], and([e1.v, e2.v, e3.v, chosen[0]])],
              ['cg', [X, 2, B], and([e1.v, e2.v, e3.v, chosen[1]])]
            ];
          }, (cg_by_1_2[keyOf([Y, 2])] || [])));
        }, (cg_by_1_2[keyOf([Y, 1])] || [])));
      }, _.values(father)));
    })()
  );
  var next_cg = relation(cg_facts, instances_cg);
  return [next_cg];
};
var stages_cg = function(rels, stage, before) {
  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_cg(stage_cg(rels), stage + 1, size) : rels;
};
var rels_cg = stages_cg([{}], 0, -1);
var cg = rels_cg[0];

var cg_by_3 = index(cg, [2]);
var cg_by_2_3 = index(cg, [1, 2]);
var instances_color = [].concat(
  // color(X,purple) :- cg(X,_,p).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      return [['color', [X, 'purple'], e1.v]];
    }, (cg_by_3[keyOf(['p'])] || [])));
  })(),
  // color(X,white) :- cg(X,1,w), cg(X,2,w).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      return _.flatten(map(function(e2) {
        return [['color', [X, 'white'], and([e1.v, e2.v])]];
      }, probe(cg, [X, 2, 'w'])));
    }, (cg_by_2_3[keyOf([1, 'w'])] || [])));
  })()
);
var color = relation({}, instances_color);

// component 0 bool
// component 1 bool
// component 2 bool
// component 3 bool
// component 4 bool
// component 5 bool
var model = function() {
  return [holds(color, ['s', 'purple'])(),
          holds(color, ['s', 'white'])(),
          holds(cg, ['s', 1, 'p'])(),
          holds(cg, ['s', 1, 'w'])(),
          holds(cg, ['s', 2, 'p'])(),
          holds(cg, ['s', 2, 'w'])()];
};
Infer({method: 'enumerate'}, model);

texts.5287e3b70dd3362f1e96fc629475d684d90e17f2:
// cplint_coin.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // the symbols as numbers: coin 1000000
  // toss/1: 1 facts
  toss_facts_1 := [1000000]: ℤ[];
  toss_facts_p := [1.0]: ℝ[];
  toss_facts_h := array(toss_facts_p.length, false);
  for i in [0..toss_facts_p.length) { if toss_facts_p[i] < 1 { toss_facts_h[i] = flip(toss_facts_p[i]); } else { toss_facts_h[i] = true; } }

  toss_1 := toss_facts_1;
  toss_h := toss_facts_h;

  demand_1_1 := []: ℤ[];
  demand_1_h := []: 𝔹[];
  // demand_1(Coin) :- toss(Coin).
  for k1 in [0..toss_h.length) {
    Coin := toss_1[k1];
    x2 := toss_h[k1];
    v3 := true;
    f4 := false;
    for k5 in [0..demand_1_h.length) {
      if demand_1_1[k5] == Coin { demand_1_h[k5] = demand_1_h[k5] || v3; f4 = true; }
    }
    if !f4 { demand_1_1 = demand_1_1 ~ [Coin]; demand_1_h = demand_1_h ~ [v3]; }
  }
  // demand_1(Coin) :- toss(Coin).
  for k6 in [0..toss_h.length) {
    Coin := toss_1[k6];
    x7 := toss_h[k6];
    v8 := true;
    f9 := false;
    for k10 in [0..demand_1_h.length) {
      if demand_1_1[k10] == Coin { demand_1_h[k10] = demand_1_h[k10] || v8; f9 = true; }
    }
    if !f9 { demand_1_1 = demand_1_1 ~ [Coin]; demand_1_h = demand_1_h ~ [v8]; }
  }

  biased_1 := []: ℤ[];
  biased_h := []: 𝔹[];
  fair_1 := []: ℤ[];
  fair_h := []: 𝔹[];
  // 0.9::fair(Coin); 0.1::biased(Coin) :- demand_1(Coin).
  for k11 in [0..demand_1_h.length) {
    Coin := demand_1_1[k11];
    x12 := demand_1_h[k11];
    c13 := categorical([0.9, 0.1]);
    v14 := x12 && c13 == 0;
    f15 := false;
    for k16 in [0..fair_h.length) {
      if fair_1[k16] == Coin { fair_h[k16] = fair_h[k16] || v14; f15 = true; }
    }
    if !f15 { fair_1 = fair_1 ~ [Coin]; fair_h = fair_h ~ [v14]; }
    v17 := x12 && c13 == 1;
    f18 := false;
    for k19 in [0..biased_h.length) {
      if biased_1[k19] == Coin { biased_h[k19] = biased_h[k19] || v17; f18 = true; }
    }
    if !f18 { biased_1 = biased_1 ~ [Coin]; biased_h = biased_h ~ [v17]; }
  }

  heads_1 := []: ℤ[];
  heads_h := []: 𝔹[];
  tails_1 := []: ℤ[];
  tails_h := []: 𝔹[];
  // 0.5::heads(Coin); 0.5::tails(Coin) :- toss(Coin), \+ biased(Coin).
  for k20 in [0..toss_h.length) {
    Coin := toss_1[k20];
    x21 := toss_h[k20];
    n22 := false;
    for k23 in [0..biased_h.length) { if biased_1[k23] == Coin { n22 = n22 || biased_h[k23]; } }
    c24 := categorical([0.5, 0.5]);
    v25 := x21 && !n22 && c24 == 0;
    f26 := false;
    for k27 in [0..heads_h.length) {
      if heads_1[k27] == Coin { heads_h[k27] = heads_h[k27] || v25; f26 = true; }
    }
    if !f26 { heads_1 = heads_1 ~ [Coin]; heads_h = heads_h ~ [v25]; }
    v28 := x21 && !n22 && c24 == 1;
    f29 := false;
    for k30 in [0..tails_h.length) {
      if tails_1[k30] == Coin { tails_h[k30] = tails_h[k30] || v28; f29 = true; }
    }
    if !f29 { tails_1 = tails_1 ~ [Coin]; tails_h = tails_h ~ [v28]; }
  }
  // 0.6::heads(Coin); 0.4::tails(Coin) :- toss(Coin), biased(Coin).
  for k31 in [0..toss_h.length) {
    Coin := toss_1[k31];
    x32 := toss_h[k31];
    for k33 in [0..biased_h.length) {
      if biased_1[k33] == Coin {
        x34 := biased_h[k33];
        c35 := categorical([0.6, 0.4]);
        v36 := x32 && x34 && c35 == 0;
        f37 := false;
        for k38 in [0..heads_h.length) {
          if heads_1[k38] == Coin { heads_h[k38] = heads_h[k38] || v36; f37 = true; }
        }
        if !f37 { heads_1 = heads_1 ~ [Coin]; heads_h = heads_h ~ [v36]; }
        v39 := x32 && x34 && c35 == 1;
        f40 := false;
        for k41 in [0..tails_h.length) {
          if tails_1[k41] == Coin { tails_h[k41] = tails_h[k41] || v39; f40 = true; }
        }
        if !f40 { tails_1 = tails_1 ~ [Coin]; tails_h = tails_h ~ [v39]; }
      }
    }
  }

  q42 := false;
  for q42_k in [0..heads_h.length) { if heads_1[q42_k] == 1000000 { q42 = heads_h[q42_k]; } }
  q43 := false;
  for q43_k in [0..tails_h.length) { if tails_1[q43_k] == 1000000 { q43 = tails_h[q43_k]; } }
  queries := [q42, q43];
  return queries[1];
}

texts.531fe083440570092ce848b8aed5298c68e84f8a:
// cplint_multiple_paths_simple.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // a/0: 1 facts
  a_facts_p := [0.3]: ℝ[];
  a_facts_h := array(a_facts_p.length, false);
  for i in [0..a_facts_p.length) { if a_facts_p[i] < 1 { a_facts_h[i] = flip(a_facts_p[i]); } else { a_facts_h[i] = true; } }
  // b/0: 1 facts
  b_facts_p := [0.4]: ℝ[];
  b_facts_h := array(b_facts_p.length, false);
  for i in [0..b_facts_p.length) { if b_facts_p[i] < 1 { b_facts_h[i] = flip(b_facts_p[i]); } else { b_facts_h[i] = true; } }

  a_h := a_facts_h;

  b_h := b_facts_h;

  p_h := []: 𝔹[];
  // p :- a, b.
  for k1 in [0..a_h.length) {
    x2 := a_h[k1];
    for k3 in [0..b_h.length) {
      x4 := b_h[k3];
      v5 := x2 && x4;
      f6 := false;
      for k7 in [0..p_h.length) {
        if true { p_h[k7] = p_h[k7] || v5; f6 = true; }
      }
      if !f6 { p_h = p_h ~ [v5]; }
    }
  }
  // p :- \+ a, \+ b.
  n8 := false;
  for k9 in [0..a_h.length) { if true { n8 = n8 || a_h[k9]; } }
  n10 := false;
  for k11 in [0..b_h.length) { if true { n10 = n10 || b_h[k11]; } }
  v12 := !n8 && !n10;
  f13 := false;
  for k14 in [0..p_h.length) {
    if true { p_h[k14] = p_h[k14] || v12; f13 = true; }
  }
  if !f13 { p_h = p_h ~ [v12]; }

  q15 := false;
  for q15_k in [0..p_h.length) { if true { q15 = p_h[q15_k]; } }
  queries := [q15];
  return queries[0];
}

texts.59960d89d8e812e279a25b3f32eab74faeef82a8:
// cplint_light.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // push/0: 1 facts
  push_facts_p := [1.0]: ℝ[];
  push_facts_h := array(push_facts_p.length, false);
  for i in [0..push_facts_p.length) { if push_facts_p[i] < 1 { push_facts_h[i] = flip(push_facts_p[i]); } else { push_facts_h[i] = true; } }

  push_h := push_facts_h;

  light_h := []: 𝔹[];
  // 0.4::light :- push.
  for k1 in [0..push_h.length) {
    x2 := push_h[k1];
    c3 := flip(0.4);
    v4 := x2 && c3;
    f5 := false;
    for k6 in [0..light_h.length) {
      if true { light_h[k6] = light_h[k6] || v4; f5 = true; }
    }
    if !f5 { light_h = light_h ~ [v4]; }
  }

  replace_h := []: 𝔹[];
  // replace :- \+ light.
  n7 := false;
  for k8 in [0..light_h.length) { if true { n7 = n7 || light_h[k8]; } }
  v9 := !n7;
  f10 := false;
  for k11 in [0..replace_h.length) {
    if true { replace_h[k11] = replace_h[k11] || v9; f10 = true; }
  }
  if !f10 { replace_h = replace_h ~ [v9]; }

  q12 := false;
  for q12_k in [0..replace_h.length) { if true { q12 = replace_h[q12_k]; } }
  q13 := false;
  for q13_k in [0..light_h.length) { if true { q13 = light_h[q13_k]; } }
  queries := [q12, q13];
  return queries[0];
}

texts.5ac49e7a2418a1c4ebdd1e0dbd9bccaf9f29fd70:
// cplint_trigger.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // the symbols as numbers: left_gun 1000000, right_gun 1000001
  // pull_trigger/1: 2 facts
  pull_trigger_facts_1 := [1000000, 1000001]: ℤ[];
  pull_trigger_facts_p := [1.0, 1.0]: ℝ[];
  pull_trigger_facts_h := array(pull_trigger_facts_p.length, false);
  for i in [0..pull_trigger_facts_p.length) { if pull_trigger_facts_p[i] < 1 { pull_trigger_facts_h[i] = flip(pull_trigger_facts_p[i]); } else { pull_trigger_facts_h[i] = true; } }

  pull_trigger_1 := pull_trigger_facts_1;
  pull_trigger_h := pull_trigger_facts_h;

  death_h := []: 𝔹[];
  // 0.16666666666666666::death :- pull_trigger(left_gun).
  for k1 in [0..pull_trigger_h.length) {
    if pull_trigger_1[k1] == 1000000 {
      x2 := pull_trigger_h[k1];
      c3 := flip(0.16666666666666666);
      v4 := x2 && c3;
      f5 := false;
      for k6 in [0..death_h.length) {
        if true { death_h[k6] = death_h[k6] || v4; f5 = true; }
      }
      if !f5 { death_h = death_h ~ [v4]; }
    }
  }
  // 0.16666666666666666::death :- pull_trigger(right_gun).
  for k7 in [0..pull_trigger_h.length) {
    if pull_trigger_1[k7] == 1000001 {
      x8 := pull_trigger_h[k7];
      c9 := flip(0.16666666666666666);
      v10 := x8 && c9;
      f11 := false;
      for k12 in [0..death_h.length) {
        if true { death_h[k12] = death_h[k12] || v10; f11 = true; }
      }
      if !f11 { death_h = death_h ~ [v10]; }
    }
  }

  q13 := false;
  for q13_k in [0..death_h.length) { if true { q13 = death_h[q13_k]; } }
  queries := [q13];
  return queries[0];
}

texts.5b22e919b20d067e0db0e660c368f14268aca674:
// cplint_earthquake.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // the symbols as numbers: eyjafjallajkull 1000000, moderate 1000001, stromboli 1000002, strong 1000003
  // fault_rupture/1: 1 facts
  fault_rupture_facts_1 := [1000002]: ℤ[];
  fault_rupture_facts_p := [1.0]: ℝ[];
  fault_rupture_facts_h := array(fault_rupture_facts_p.length, false);
  for i in [0..fault_rupture_facts_p.length) { if fault_rupture_facts_p[i] < 1 { fault_rupture_facts_h[i] = flip(fault_rupture_facts_p[i]); } else { fault_rupture_facts_h[i] = true; } }
  // volcanic_eruption/1: 2 facts
  volcanic_eruption_facts_1 := [1000002, 1000000]: ℤ[];
  volcanic_eruption_facts_p := [1.0, 1.0]: ℝ[];
  volcanic_eruption_facts_h := array(volcanic_eruption_facts_p.length, false);
  for i in [0..volcanic_eruption_facts_p.length) { if volcanic_eruption_facts_p[i] < 1 { volcanic_eruption_facts_h[i] = flip(volcanic_eruption_facts_p[i]); } else { volcanic_eruption_facts_h[i] = true; } }

  fault_rupture_1 := fault_rupture_facts_1;
