  for i in [0..cg_facts_p.length) { if cg_facts_p[i] < 1 { cg_facts_h[i] = flip(cg_facts_p[i]); } else { cg_facts_h[i] = true; } }

  father_1 := father_facts_1;
  father_2 := father_facts_2;
  father_h := father_facts_h;

  mother_1 := mother_facts_1;
  mother_2 := mother_facts_2;
  mother_h := mother_facts_h;

  // cg/3: recursive; the rules applied in stages from no tuple,
  // each reading the stage before, until a stage adds no tuple and the stages number the tuples
  // the draws of `0.5::cg(X,1,A); 0.5::cg(X,1,B) :- mother(Y,X), cg(Y,1,A), cg(Y,2,B).`, by instance
  coins3_1 := []: ℤ[];
  coins3_2 := []: ℤ[];
  coins3_3 := []: ℤ[];
  coins3_4 := []: ℤ[];
  coins3_c := []: ℕ[];
  // the draws of `0.5::cg(X,2,A); 0.5::cg(X,2,B) :- father(Y,X), cg(Y,1,A), cg(Y,2,B).`, by instance
  coins4_1 := []: ℤ[];
  coins4_2 := []: ℤ[];
  coins4_3 := []: ℤ[];
  coins4_4 := []: ℤ[];
  coins4_c := []: ℕ[];
  cg_1 := []: ℤ[];
  cg_2 := []: ℤ[];
  cg_3 := []: ℤ[];
  cg_h := []: 𝔹[];
  stage1 := 0;
  before2 := -1;
  while stage1 < cg_h.length || cg_h.length != before2 {
    before2 = cg_h.length;
    next_cg_1 := cg_facts_1;
    next_cg_2 := cg_facts_2;
    next_cg_3 := cg_facts_3;
    next_cg_h := cg_facts_h;
    // 0.5::cg(X,1,A); 0.5::cg(X,1,B) :- mother(Y,X), cg(Y,1,A), cg(Y,2,B).
    for k3 in [0..mother_h.length) {
      Y := mother_1[k3];
      X := mother_2[k3];
      x4 := mother_h[k3];
      for k5 in [0..cg_h.length) {
        if cg_1[k5] == Y && cg_2[k5] == 1 {
          A := cg_3[k5];
          x6 := cg_h[k5];
          for k7 in [0..cg_h.length) {
            if cg_1[k7] == Y && cg_2[k7] == 2 {
              B := cg_3[k7];
              x8 := cg_h[k7];
              c9 := 0;
              g10 := false;
              for k11 in [0..coins3_c.length) { if coins3_1[k11] == X && coins3_2[k11] == A && coins3_3[k11] == B && coins3_4[k11] == Y { c9 = coins3_c[k11]; g10 = true; } }
              if !g10 { c9 = categorical([0.5, 0.5]); coins3_1 = coins3_1 ~ [X]; coins3_2 = coins3_2 ~ [A]; coins3_3 = coins3_3 ~ [B]; coins3_4 = coins3_4 ~ [Y]; coins3_c = coins3_c ~ [c9]; }
              v12 := x4 && x6 && x8 && c9 == 0;
              f13 := false;
              for k14 in [0..next_cg_h.length) {
                if next_cg_1[k14] == X && next_cg_2[k14] == 1 && next_cg_3[k14] == A { next_cg_h[k14] = next_cg_h[k14] || v12; f13 = true; }
              }
              if !f13 { next_cg_1 = next_cg_1 ~ [X]; next_cg_2 = next_cg_2 ~ [1]; next_cg_3 = next_cg_3 ~ [A]; next_cg_h = next_cg_h ~ [v12]; }
              v15 := x4 && x6 && x8 && c9 == 1;
              f16 := false;
              for k17 in [0..next_cg_h.length) {
                if next_cg_1[k17] == X && next_cg_2[k17] == 1 && next_cg_3[k17] == B { next_cg_h[k17] = next_cg_h[k17] || v15; f16 = true; }
              }
              if !f16 { next_cg_1 = next_cg_1 ~ [X]; next_cg_2 = next_cg_2 ~ [1]; next_cg_3 = next_cg_3 ~ [B]; next_cg_h = next_cg_h ~ [v15]; }
            }
          }
        }
      }
    }
    // 0.5::cg(X,2,A); 0.5::cg(X,2,B) :- father(Y,X), cg(Y,1,A), cg(Y,2,B).
    for k18 in [0..father_h.length) {
      Y := father_1[k18];
      X := father_2[k18];
      x19 := father_h[k18];
      for k20 in [0..cg_h.length) {
        if cg_1[k20] == Y && cg_2[k20] == 1 {
          A := cg_3[k20];
          x21 := cg_h[k20];
          for k22 in [0..cg_h.length) {
            if cg_1[k22] == Y && cg_2[k22] == 2 {
              B := cg_3[k22];
              x23 := cg_h[k22];
              c24 := 0;
              g25 := false;
              for k26 in [0..coins4_c.length) { if coins4_1[k26] == X && coins4_2[k26] == A && coins4_3[k26] == B && coins4_4[k26] == Y { c24 = coins4_c[k26]; g25 = true; } }
              if !g25 { c24 = categorical([0.5, 0.5]); coins4_1 = coins4_1 ~ [X]; coins4_2 = coins4_2 ~ [A]; coins4_3 = coins4_3 ~ [B]; coins4_4 = coins4_4 ~ [Y]; coins4_c = coins4_c ~ [c24]; }
              v27 := x19 && x21 && x23 && c24 == 0;
              f28 := false;
              for k29 in [0..next_cg_h.length) {
                if next_cg_1[k29] == X && next_cg_2[k29] == 2 && next_cg_3[k29] == A { next_cg_h[k29] = next_cg_h[k29] || v27; f28 = true; }
              }
              if !f28 { next_cg_1 = next_cg_1 ~ [X]; next_cg_2 = next_cg_2 ~ [2]; next_cg_3 = next_cg_3 ~ [A]; next_cg_h = next_cg_h ~ [v27]; }
              v30 := x19 && x21 && x23 && c24 == 1;
              f31 := false;
              for k32 in [0..next_cg_h.length) {
                if next_cg_1[k32] == X && next_cg_2[k32] == 2 && next_cg_3[k32] == B { next_cg_h[k32] = next_cg_h[k32] || v30; f31 = true; }
              }
              if !f31 { next_cg_1 = next_cg_1 ~ [X]; next_cg_2 = next_cg_2 ~ [2]; next_cg_3 = next_cg_3 ~ [B]; next_cg_h = next_cg_h ~ [v30]; }
            }
          }
        }
      }
    }
    cg_1 = next_cg_1;
    cg_2 = next_cg_2;
    cg_3 = next_cg_3;
    cg_h = next_cg_h;
    stage1 = stage1 + 1;
  }

  color_1 := []: ℤ[];
  color_2 := []: ℤ[];
  color_h := []: 𝔹[];
  // color(X,purple) :- cg(X,_,p).
  for k33 in [0..cg_h.length) {
    if cg_3[k33] == 1000002 {
      X := cg_1[k33];
      x34 := cg_h[k33];
      v35 := x34;
      f36 := false;
      for k37 in [0..color_h.length) {
        if color_1[k37] == X && color_2[k37] == 1000003 { color_h[k37] = color_h[k37] || v35; f36 = true; }
      }
      if !f36 { color_1 = color_1 ~ [X]; color_2 = color_2 ~ [1000003]; color_h = color_h ~ [v35]; }
    }
  }
  // color(X,white) :- cg(X,1,w), cg(X,2,w).
  for k38 in [0..cg_h.length) {
    if cg_2[k38] == 1 && cg_3[k38] == 1000005 {
      X := cg_1[k38];
      x39 := cg_h[k38];
      for k40 in [0..cg_h.length) {
        if cg_1[k40] == X && cg_2[k40] == 2 && cg_3[k40] == 1000005 {
          x41 := cg_h[k40];
          v42 := x39 && x41;
          f43 := false;
          for k44 in [0..color_h.length) {
            if color_1[k44] == X && color_2[k44] == 1000006 { color_h[k44] = color_h[k44] || v42; f43 = true; }
          }
          if !f43 { color_1 = color_1 ~ [X]; color_2 = color_2 ~ [1000006]; color_h = color_h ~ [v42]; }
        }
      }
    }
  }

  q45 := false;
  for q45_k in [0..color_h.length) { if color_1[q45_k] == 1000004 && color_2[q45_k] == 1000003 { q45 = color_h[q45_k]; } }
  q46 := false;
  for q46_k in [0..color_h.length) { if color_1[q46_k] == 1000004 && color_2[q46_k] == 1000006 { q46 = color_h[q46_k]; } }
  q47 := false;
  for q47_k in [0..cg_h.length) { if cg_1[q47_k] == 1000004 && cg_2[q47_k] == 1 && cg_3[q47_k] == 1000002 { q47 = cg_h[q47_k]; } }
  q48 := false;
  for q48_k in [0..cg_h.length) { if cg_1[q48_k] == 1000004 && cg_2[q48_k] == 1 && cg_3[q48_k] == 1000005 { q48 = cg_h[q48_k]; } }
  q49 := false;
  for q49_k in [0..cg_h.length) { if cg_1[q49_k] == 1000004 && cg_2[q49_k] == 2 && cg_3[q49_k] == 1000002 { q49 = cg_h[q49_k]; } }
  q50 := false;
  for q50_k in [0..cg_h.length) { if cg_1[q50_k] == 1000004 && cg_2[q50_k] == 2 && cg_3[q50_k] == 1000005 { q50 = cg_h[q50_k]; } }
  queries := [q45, q46, q47, q48, q49, q50];
  return queries[5];
}

texts.8fdbe886e08e1c095afa5f94a0fc9eebe967787b:
// cplint_coin2.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // the symbols as numbers: coin1 1000000, coin2 1000001
  // toss/1: 2 facts
  toss_facts_1 := [1000000, 1000001]: ℤ[];
  toss_facts_p := [1.0, 1.0]: ℝ[];
  toss_facts_h := array(toss_facts_p.length, false);
  for i in [0..toss_facts_p.length) { if toss_facts_p[i] < 1 { toss_facts_h[i] = flip(toss_facts_p[i]); } else { toss_facts_h[i] = true; } }

  toss_1 := toss_facts_1;
  toss_h := toss_facts_h;

  demand_1_1 := []: ℤ[];
  demand_1_h := []: 𝔹[];
  // demand_1(Coin) :- toss(Coin).
  for k1 in [0..toss_h.length) {
    Coin := toss_1[k1];
    x2 := toss_h[k1];
    v3 := true;
    f4 := false;
    for k5 in [0..demand_1_h.length) {
      if demand_1_1[k5] == Coin { demand_1_h[k5] = demand_1_h[k5] || v3; f4 = true; }
    }
    if !f4 { demand_1_1 = demand_1_1 ~ [Coin]; demand_1_h = demand_1_h ~ [v3]; }
  }
  // demand_1(Coin) :- toss(Coin).
  for k6 in [0..toss_h.length) {
    Coin := toss_1[k6];
    x7 := toss_h[k6];
    v8 := true;
    f9 := false;
    for k10 in [0..demand_1_h.length) {
      if demand_1_1[k10] == Coin { demand_1_h[k10] = demand_1_h[k10] || v8; f9 = true; }
    }
    if !f9 { demand_1_1 = demand_1_1 ~ [Coin]; demand_1_h = demand_1_h ~ [v8]; }
  }

  biased_1 := []: ℤ[];
  biased_h := []: 𝔹[];
  fair_1 := []: ℤ[];
  fair_h := []: 𝔹[];
  // 0.9::fair(Coin); 0.1::biased(Coin) :- demand_1(Coin).
  for k11 in [0..demand_1_h.length) {
    Coin := demand_1_1[k11];
    x12 := demand_1_h[k11];
    c13 := categorical([0.9, 0.1]);
    v14 := x12 && c13 == 0;
    f15 := false;
    for k16 in [0..fair_h.length) {
      if fair_1[k16] == Coin { fair_h[k16] = fair_h[k16] || v14; f15 = true; }
    }
    if !f15 { fair_1 = fair_1 ~ [Coin]; fair_h = fair_h ~ [v14]; }
    v17 := x12 && c13 == 1;
    f18 := false;
    for k19 in [0..biased_h.length) {
      if biased_1[k19] == Coin { biased_h[k19] = biased_h[k19] || v17; f18 = true; }
    }
    if !f18 { biased_1 = biased_1 ~ [Coin]; biased_h = biased_h ~ [v17]; }
  }

  heads_1 := []: ℤ[];
  heads_h := []: 𝔹[];
  tails_1 := []: ℤ[];
  tails_h := []: 𝔹[];
  // 0.5::heads(Coin); 0.5::tails(Coin) :- toss(Coin), fair(Coin).
  for k20 in [0..toss_h.length) {
    Coin := toss_1[k20];
    x21 := toss_h[k20];
    for k22 in [0..fair_h.length) {
      if fair_1[k22] == Coin {
        x23 := fair_h[k22];
        c24 := categorical([0.5, 0.5]);
        v25 := x21 && x23 && c24 == 0;
        f26 := false;
        for k27 in [0..heads_h.length) {
          if heads_1[k27] == Coin { heads_h[k27] = heads_h[k27] || v25; f26 = true; }
        }
        if !f26 { heads_1 = heads_1 ~ [Coin]; heads_h = heads_h ~ [v25]; }
        v28 := x21 && x23 && c24 == 1;
        f29 := false;
        for k30 in [0..tails_h.length) {
          if tails_1[k30] == Coin { tails_h[k30] = tails_h[k30] || v28; f29 = true; }
        }
        if !f29 { tails_1 = tails_1 ~ [Coin]; tails_h = tails_h ~ [v28]; }
      }
    }
  }
  // 0.6::heads(Coin); 0.4::tails(Coin) :- toss(Coin), biased(Coin).
  for k31 in [0..toss_h.length) {
    Coin := toss_1[k31];
    x32 := toss_h[k31];
    for k33 in [0..biased_h.length) {
      if biased_1[k33] == Coin {
        x34 := biased_h[k33];
        c35 := categorical([0.6, 0.4]);
        v36 := x32 && x34 && c35 == 0;
        f37 := false;
        for k38 in [0..heads_h.length) {
          if heads_1[k38] == Coin { heads_h[k38] = heads_h[k38] || v36; f37 = true; }
        }
        if !f37 { heads_1 = heads_1 ~ [Coin]; heads_h = heads_h ~ [v36]; }
        v39 := x32 && x34 && c35 == 1;
        f40 := false;
        for k41 in [0..tails_h.length) {
          if tails_1[k41] == Coin { tails_h[k41] = tails_h[k41] || v39; f40 = true; }
        }
        if !f40 { tails_1 = tails_1 ~ [Coin]; tails_h = tails_h ~ [v39]; }
      }
    }
  }

  q42 := false;
  for q42_k in [0..heads_h.length) { if heads_1[q42_k] == 1000001 { q42 = heads_h[q42_k]; } }
  q43 := false;
  for q43_k in [0..tails_h.length) { if tails_1[q43_k] == 1000001 { q43 = tails_h[q43_k]; } }
  q44 := false;
  for q44_k in [0..heads_h.length) { if heads_1[q44_k] == 1000000 { q44 = heads_h[q44_k]; } }
  q45 := false;
  for q45_k in [0..tails_h.length) { if tails_1[q45_k] == 1000000 { q45 = tails_h[q45_k]; } }
  queries := [q42, q43, q44, q45];
  return queries[0];
}

texts.92307c7550378aef6c178c509c6c665cf9dc1a49:
// cplint_markov_network.pl: a ProbLog program written in WebPPL by tddlog's
// scripts/problog2ppl.py, first order as it is written. A relation is an
// object from a tuple's key to {t: the tuple, v: whether it holds}, v a
// function of no arguments that says whether the tuple holds in the world
// being enumerated, memoized within it; each probabilistic fact is a coin of
// its own (`flip`), drawn where a world first reads it; a rule's instances
// are maps over the relations its body joins. The facts are lpFacts, which
// the runner reads from the facts file: {relation: [[argument ...,
// probability], ...]}. The queries are enumerated exactly, given the
// evidence.

var yes = function() { return true; };
var no = function() { return false; };
// a coin of probability p, drawn once in a world
var coin = function(p) { return mem(function() { return flip(p); }); };
var and = function(xs) { return function() { return all(function(x) { return x(); }, xs); }; };
var not = function(x) { return function() { return !x(); }; };
var keyOf = function(t) { return JSON.stringify(t); };
// whether the tuple t of r holds
var holds = function(r, t) { var e = r[keyOf(t)]; return e ? e.v : no; };
// the entry of t, if it is a tuple of r: none or one to map over
var probe = function(r, t) { var e = r[keyOf(t)]; return e ? [e] : []; };
// the entries of r by their values at positions ps (from 0)
var index = function(r, ps) {
  return _.groupBy(map(function(e) { return {k: keyOf(_.at(e.t, ps)), t: e.t, v: e.v}; }, _.values(r)), 'k');
};
// whether a tuple of the index's key k holds
var holdsAny = function(ix, k) {
  var es = ix[keyOf(k)] || [];
  return function() { return any(function(e) { return e.v(); }, es); };
};
// the choice of an annotated disjunction p1::h1; ...; pn::hn: whether each
// head is the one chosen, the k-th with probability pk and none with the rest
var choose = function(ps) {
  var rest = 1 - sum(ps);
  var vs = _.range(ps.length + (rest > 0 ? 1 : 0));
  var c = mem(function() { return categorical({ps: rest > 0 ? ps.concat([rest]) : ps, vs: vs}); });
  return map(function(k) { return function() { return c() === k; }; }, _.range(ps.length));
};
// the instances, [relation, tuple, holding] each, of relation `name`
var only = function(name, instances) { return filter(function(i) { return i[0] === name; }, instances); };
// the relation of base and instances: a tuple holds where its fact or one
// of its instances does
var relation = function(base, instances) {
  var entries = map(function(e) { return {k: keyOf(e.t), t: e.t, v: e.v}; }, _.values(base)).concat(
    map(function(i) { return {k: keyOf(i[1]), t: i[1], v: i[2]}; }, instances));
  return mapObject(function(k, es) {
    var vs = map(function(e) { return e.v; }, es);
    return {t: es[0].t, v: mem(function() { return any(function(x) { return x(); }, vs); })};
  }, _.groupBy(entries, 'k'));
};
// a relation of facts, [argument ..., probability] each
var relationOfFacts = function(rows) {
  return _.fromPairs(map(function(row) {
    var t = row.slice(0, row.length - 1), p = row[row.length - 1];
    return [keyOf(t), {t: t, v: p >= 1 ? yes : coin(p)}];
  }, rows));
};

var intelligent_facts = relationOfFacts(lpFacts['intelligent/0'] || []);
var good_marks_facts = relationOfFacts(lpFacts['good_marks/0'] || []);
var difficult_course_facts = relationOfFacts(lpFacts['difficult_course/0'] || []);
var good_teacher_facts = relationOfFacts(lpFacts['good_teacher/0'] || []);

var difficult_course = difficult_course_facts;

var good_marks = good_marks_facts;

var intelligent = intelligent_facts;

var instances_factor1 = [].concat(
  // 0.3::factor1 :- \+ intelligent, \+ good_marks.
  (function() {
    return [['factor1', [], and([not(holds(intelligent, [])), not(holds(good_marks, [])), coin(0.3)])]];
  })(),
  // 0.3::factor1 :- \+ intelligent, good_marks.
  (function() {
    return _.flatten(map(function(e1) {
      return [['factor1', [], and([not(holds(intelligent, [])), e1.v, coin(0.3)])]];
    }, probe(good_marks, [])));
  })(),
  // 0.1::factor1 :- intelligent, \+ good_marks.
  (function() {
    return _.flatten(map(function(e1) {
      return [['factor1', [], and([not(holds(good_marks, [])), e1.v, coin(0.1)])]];
    }, probe(intelligent, [])));
  })(),
  // 0.3::factor1 :- intelligent, good_marks.
  (function() {
    return _.flatten(map(function(e1) {
      return _.flatten(map(function(e2) {
        return [['factor1', [], and([e1.v, e2.v, coin(0.3)])]];
      }, probe(good_marks, [])));
    }, probe(intelligent, [])));
  })()
);
var factor1 = relation({}, instances_factor1);

var instances_factor2 = [].concat(
  // 0.3::factor2 :- \+ difficult_course, \+ good_marks.
  (function() {
    return [['factor2', [], and([not(holds(difficult_course, [])), not(holds(good_marks, [])), coin(0.3)])]];
  })(),
  // 0.3::factor2 :- \+ difficult_course, good_marks.
  (function() {
    return _.flatten(map(function(e1) {
      return [['factor2', [], and([not(holds(difficult_course, [])), e1.v, coin(0.3)])]];
    }, probe(good_marks, [])));
  })(),
  // 0.3::factor2 :- difficult_course, \+ good_marks.
  (function() {
    return _.flatten(map(function(e1) {
      return [['factor2', [], and([not(holds(good_marks, [])), e1.v, coin(0.3)])]];
    }, probe(difficult_course, [])));
  })(),
  // 0.1::factor2 :- difficult_course, good_marks.
  (function() {
    return _.flatten(map(function(e1) {
      return _.flatten(map(function(e2) {
        return [['factor2', [], and([e1.v, e2.v, coin(0.1)])]];
      }, probe(good_marks, [])));
    }, probe(difficult_course, [])));
  })()
);
var factor2 = relation({}, instances_factor2);

var good_teacher = good_teacher_facts;

var instances_factor3 = [].concat(
  // 0.3::factor3 :- \+ good_teacher, \+ good_marks.
  (function() {
    return [['factor3', [], and([not(holds(good_teacher, [])), not(holds(good_marks, [])), coin(0.3)])]];
  })(),
  // 0.3::factor3 :- \+ good_teacher, good_marks.
  (function() {
    return _.flatten(map(function(e1) {
      return [['factor3', [], and([not(holds(good_teacher, [])), e1.v, coin(0.3)])]];
    }, probe(good_marks, [])));
  })(),
  // 0.1::factor3 :- good_teacher, \+ good_marks.
  (function() {
    return _.flatten(map(function(e1) {
      return [['factor3', [], and([not(holds(good_marks, [])), e1.v, coin(0.1)])]];
    }, probe(good_teacher, [])));
  })(),
