  (function() {
    return [['factor4', [], and([not(holds(difficult_course, [])), not(holds(good_teacher, [])), coin(0.3)])]];
  })(),
  // 0.3::factor4 :- \+ difficult_course, good_teacher.
  (function() {
    return _.flatten(map(function(e1) {
      return [['factor4', [], and([not(holds(difficult_course, [])), e1.v, coin(0.3)])]];
    }, probe(good_teacher, [])));
  })(),
  // 0.3::factor4 :- difficult_course, \+ good_teacher.
  (function() {
