// cplint_markov_factor.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // a/0: 1 facts
  a_facts_p := [0.5]: ℝ[];
  a_facts_h := array(a_facts_p.length, false);
  for i in [0..a_facts_p.length) { if a_facts_p[i] < 1 { a_facts_h[i] = flip(a_facts_p[i]); } else { a_facts_h[i] = true; } }
  // b/0: 1 facts
  b_facts_p := [0.5]: ℝ[];
  b_facts_h := array(b_facts_p.length, false);
  for i in [0..b_facts_p.length) { if b_facts_p[i] < 1 { b_facts_h[i] = flip(b_facts_p[i]); } else { b_facts_h[i] = true; } }

  a_h := a_facts_h;

  b_h := b_facts_h;

  p_h := []: 𝔹[];
  // 0.3::p :- a, b.
  for k1 in [0..a_h.length) {
    x2 := a_h[k1];
    for k3 in [0..b_h.length) {
      x4 := b_h[k3];
      c5 := flip(0.3);
      v6 := x2 && x4 && c5;
      f7 := false;
      for k8 in [0..p_h.length) {
        if true { p_h[k8] = p_h[k8] || v6; f7 = true; }
      }
      if !f7 { p_h = p_h ~ [v6]; }
    }
  }
  // 0.7::p :- \+ a, b.
  n9 := false;
  for k10 in [0..a_h.length) { if true { n9 = n9 || a_h[k10]; } }
  for k11 in [0..b_h.length) {
    x12 := b_h[k11];
    c13 := flip(0.7);
    v14 := !n9 && x12 && c13;
    f15 := false;
    for k16 in [0..p_h.length) {
      if true { p_h[k16] = p_h[k16] || v14; f15 = true; }
    }
    if !f15 { p_h = p_h ~ [v14]; }
  }
  // 0.4::p :- \+ a, \+ b.
  n17 := false;
  for k18 in [0..a_h.length) { if true { n17 = n17 || a_h[k18]; } }
  n19 := false;
  for k20 in [0..b_h.length) { if true { n19 = n19 || b_h[k20]; } }
  c21 := flip(0.4);
  v22 := !n17 && !n19 && c21;
  f23 := false;
  for k24 in [0..p_h.length) {
    if true { p_h[k24] = p_h[k24] || v22; f23 = true; }
  }
  if !f23 { p_h = p_h ~ [v22]; }
  // 0.6::p :- a, \+ b.
  n25 := false;
  for k26 in [0..b_h.length) { if true { n25 = n25 || b_h[k26]; } }
  for k27 in [0..a_h.length) {
    x28 := a_h[k27];
    c29 := flip(0.6);
    v30 := !n25 && x28 && c29;
    f31 := false;
    for k32 in [0..p_h.length) {
      if true { p_h[k32] = p_h[k32] || v30; f31 = true; }
    }
    if !f31 { p_h = p_h ~ [v30]; }
  }

  evidence__h := []: 𝔹[];
  // evidence :- p, b.
  for k33 in [0..p_h.length) {
    x34 := p_h[k33];
    for k35 in [0..b_h.length) {
      x36 := b_h[k35];
      v37 := x34 && x36;
      f38 := false;
      for k39 in [0..evidence__h.length) {
        if true { evidence__h[k39] = evidence__h[k39] || v37; f38 = true; }
      }
      if !f38 { evidence__h = evidence__h ~ [v37]; }
    }
  }

  q40 := false;
  for q40_k in [0..a_h.length) { if true { q40 = a_h[q40_k]; } }
  e41 := false;
  for e41_k in [0..evidence__h.length) { if true { e41 = evidence__h[e41_k]; } }
  observe(e41);
  queries := [q40];
  return queries[0];
}

