  }
  // 0.1::factor3 :- good_teacher, \+ good_marks.
  n81 := false;
  for k82 in [0..good_marks_h.length) { if true { n81 = n81 || good_marks_h[k82]; } }
  for k83 in [0..good_teacher_h.length) {
    x84 := good_teacher_h[k83];
    c85 := flip(0.1);
    v86 := !n81 && x84 && c85;
    f87 := false;
    for k88 in [0..factor3_h.length) {
      if true { factor3_h[k88] = factor3_h[k88] || v86; f87 = true; }
    }
    if !f87 { factor3_h = factor3_h ~ [v86]; }
  }
  // 0.3::factor3 :- good_teacher, good_marks.
  for k89 in [0..good_teacher_h.length) {
    x90 := good_teacher_h[k89];
    for k91 in [0..good_marks_h.length) {
      x92 := good_marks_h[k91];
      c93 := flip(0.3);
      v94 := x90 && x92 && c93;
      f95 := false;
      for k96 in [0..factor3_h.length) {
        if true { factor3_h[k96] = factor3_h[k96] || v94; f95 = true; }
      }
      if !f95 { factor3_h = factor3_h ~ [v94]; }
    }
  }

  factor4_h := []: 𝔹[];
  // 0.3::factor4 :- \+ difficult_course, \+ good_teacher.
  n97 := false;
  for k98 in [0..difficult_course_h.length) { if true { n97 = n97 || difficult_course_h[k98]; } }
  n99 := false;
  for k100 in [0..good_teacher_h.length) { if true { n99 = n99 || good_teacher_h[k100]; } }
  c101 := flip(0.3);
  v102 := !n97 && !n99 && c101;
  f103 := false;
  for k104 in [0..factor4_h.length) {
    if true { factor4_h[k104] = factor4_h[k104] || v102; f103 = true; }
  }
  if !f103 { factor4_h = factor4_h ~ [v102]; }
  // 0.3::factor4 :- \+ difficult_course, good_teacher.
  n105 := false;
  for k106 in [0..difficult_course_h.length) { if true { n105 = n105 || difficult_course_h[k106]; } }
  for k107 in [0..good_teacher_h.length) {
    x108 := good_teacher_h[k107];
    c109 := flip(0.3);
    v110 := !n105 && x108 && c109;
    f111 := false;
    for k112 in [0..factor4_h.length) {
      if true { factor4_h[k112] = factor4_h[k112] || v110; f111 = true; }
    }
    if !f111 { factor4_h = factor4_h ~ [v110]; }
  }
  // 0.3::factor4 :- difficult_course, \+ good_teacher.
  n113 := false;
  for k114 in [0..good_teacher_h.length) { if true { n113 = n113 || good_teacher_h[k114]; } }
  for k115 in [0..difficult_course_h.length) {
    x116 := difficult_course_h[k115];
    c117 := flip(0.3);
    v118 := !n113 && x116 && c117;
    f119 := false;
    for k120 in [0..factor4_h.length) {
