  }
  // 0.1::factor4 :- difficult_course, good_teacher.
  for k121 in [0..difficult_course_h.length) {
    x122 := difficult_course_h[k121];
    for k123 in [0..good_teacher_h.length) {
      x124 := good_teacher_h[k123];
      c125 := flip(0.1);
      v126 := x122 && x124 && c125;
      f127 := false;
      for k128 in [0..factor4_h.length) {
        if true { factor4_h[k128] = factor4_h[k128] || v126; f127 = true; }
      }
      if !f127 { factor4_h = factor4_h ~ [v126]; }
    }
  }

  evidence__h := []: 𝔹[];
  // evidence :- factor1, factor2, factor3, factor4.
  for k129 in [0..factor1_h.length) {
    x130 := factor1_h[k129];
    for k131 in [0..factor2_h.length) {
      x132 := factor2_h[k131];
      for k133 in [0..factor3_h.length) {
        x134 := factor3_h[k133];
        for k135 in [0..factor4_h.length) {
          x136 := factor4_h[k135];
          v137 := x130 && x132 && x134 && x136;
          f138 := false;
          for k139 in [0..evidence__h.length) {
            if true { evidence__h[k139] = evidence__h[k139] || v137; f138 = true; }
          }
          if !f138 { evidence__h = evidence__h ~ [v137]; }
        }
      }
    }
  }

  q140 := false;
  for q140_k in [0..good_marks_h.length) { if true { q140 = good_marks_h[q140_k]; } }
  e141 := false;
  for e141_k in [0..evidence__h.length) { if true { e141 = evidence__h[e141_k]; } }
  observe(e141);
  queries := [q140];
  return queries[0];
}

