var hay_fever_facts = relationOfFacts(lpFacts['hay_fever/1'] || []);

var flu = flu_facts;

var hay_fever = hay_fever_facts;

var instances_moderate_sneezing = [].concat(
  // 0.3::strong_sneezing(X); 0.5::moderate_sneezing(X) :- flu(X).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      var chosen = choose([0.3, 0.5]);
      return [
        ['strong_sneezing', [X], and([e1.v, chosen[0]])],
        ['moderate_sneezing', [X], and([e1.v, chosen[1]])]
      ];
    }, _.values(flu)));
  })(),
  // 0.2::strong_sneezing(X); 0.6::moderate_sneezing(X) :- hay_fever(X).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      var chosen = choose([0.2, 0.6]);
      return [
        ['strong_sneezing', [X], and([e1.v, chosen[0]])],
        ['moderate_sneezing', [X], and([e1.v, chosen[1]])]
      ];
    }, _.values(hay_fever)));
  })()
);
var moderate_sneezing = relation({}, only('moderate_sneezing', instances_moderate_sneezing));
var strong_sneezing = relation({}, only('strong_sneezing', instances_moderate_sneezing));

// component 0 bool
// component 1 bool
var model = function() {
  return [holds(strong_sneezing, ['bob'])(),
          holds(moderate_sneezing, ['bob'])()];
};
Infer({method: 'enumerate'}, model);

