    for k18 in [0..father_h.length) {
      Y := father_1[k18];
      X := father_2[k18];
      x19 := father_h[k18];
      for k20 in [0..cg_h.length) {
        if cg_1[k20] == Y && cg_2[k20] == 1 {
          A := cg_3[k20];
          x21 := cg_h[k20];
          for k22 in [0..cg_h.length) {
            if cg_1[k22] == Y && cg_2[k22] == 2 {
              B := cg_3[k22];
              x23 := cg_h[k22];
              c24 := 0;
              g25 := false;
              for k26 in [0..coins4_c.length) { if coins4_1[k26] == X && coins4_2[k26] == A && coins4_3[k26] == B && coins4_4[k26] == Y { c24 = coins4_c[k26]; g25 = true; } }
              if !g25 { c24 = categorical([0.5, 0.5]); coins4_1 = coins4_1 ~ [X]; coins4_2 = coins4_2 ~ [A]; coins4_3 = coins4_3 ~ [B]; coins4_4 = coins4_4 ~ [Y]; coins4_c = coins4_c ~ [c24]; }
              v27 := x19 && x21 && x23 && c24 == 0;
              f28 := false;
              for k29 in [0..next_cg_h.length) {
                if next_cg_1[k29] == X && next_cg_2[k29] == 2 && next_cg_3[k29] == A { next_cg_h[k29] = next_cg_h[k29] || v27; f28 = true; }
              }
              if !f28 { next_cg_1 = next_cg_1 ~ [X]; next_cg_2 = next_cg_2 ~ [2]; next_cg_3 = next_cg_3 ~ [A]; next_cg_h = next_cg_h ~ [v27]; }
              v30 := x19 && x21 && x23 && c24 == 1;
              f31 := false;
              for k32 in [0..next_cg_h.length) {
                if next_cg_1[k32] == X && next_cg_2[k32] == 2 && next_cg_3[k32] == B { next_cg_h[k32] = next_cg_h[k32] || v30; f31 = true; }
              }
              if !f31 { next_cg_1 = next_cg_1 ~ [X]; next_cg_2 = next_cg_2 ~ [2]; next_cg_3 = next_cg_3 ~ [B]; next_cg_h = next_cg_h ~ [v30]; }
            }
          }
        }
      }
    }
    cg_1 = next_cg_1;
    cg_2 = next_cg_2;
    cg_3 = next_cg_3;
    cg_h = next_cg_h;
    stage1 = stage1 + 1;
  }

  color_1 := []: ℤ[];
  color_2 := []: ℤ[];
  color_h := []: 𝔹[];
  // color(X,purple) :- cg(X,_,p).
  for k33 in [0..cg_h.length) {
    if cg_3[k33] == 1000002 {
      X := cg_1[k33];
      x34 := cg_h[k33];
      v35 := x34;
      f36 := false;
      for k37 in [0..color_h.length) {
        if color_1[k37] == X && color_2[k37] == 1000003 { color_h[k37] = color_h[k37] || v35; f36 = true; }
      }
      if !f36 { color_1 = color_1 ~ [X]; color_2 = color_2 ~ [1000003]; color_h = color_h ~ [v35]; }
    }
  }
  // color(X,white) :- cg(X,1,w), cg(X,2,w).
  for k38 in [0..cg_h.length) {
    if cg_2[k38] == 1 && cg_3[k38] == 1000005 {
      X := cg_1[k38];
      x39 := cg_h[k38];
      for k40 in [0..cg_h.length) {
        if cg_1[k40] == X && cg_2[k40] == 2 && cg_3[k40] == 1000005 {
          x41 := cg_h[k40];
          v42 := x39 && x41;
          f43 := false;
          for k44 in [0..color_h.length) {
            if color_1[k44] == X && color_2[k44] == 1000006 { color_h[k44] = color_h[k44] || v42; f43 = true; }
          }
          if !f43 { color_1 = color_1 ~ [X]; color_2 = color_2 ~ [1000006]; color_h = color_h ~ [v42]; }
        }
      }
    }
  }

  q45 := false;
  for q45_k in [0..color_h.length) { if color_1[q45_k] == 1000004 && color_2[q45_k] == 1000003 { q45 = color_h[q45_k]; } }
  q46 := false;
  for q46_k in [0..color_h.length) { if color_1[q46_k] == 1000004 && color_2[q46_k] == 1000006 { q46 = color_h[q46_k]; } }
  q47 := false;
  for q47_k in [0..cg_h.length) { if cg_1[q47_k] == 1000004 && cg_2[q47_k] == 1 && cg_3[q47_k] == 1000002 { q47 = cg_h[q47_k]; } }
  q48 := false;
  for q48_k in [0..cg_h.length) { if cg_1[q48_k] == 1000004 && cg_2[q48_k] == 1 && cg_3[q48_k] == 1000005 { q48 = cg_h[q48_k]; } }
  q49 := false;
  for q49_k in [0..cg_h.length) { if cg_1[q49_k] == 1000004 && cg_2[q49_k] == 2 && cg_3[q49_k] == 1000002 { q49 = cg_h[q49_k]; } }
  q50 := false;
  for q50_k in [0..cg_h.length) { if cg_1[q50_k] == 1000004 && cg_2[q50_k] == 2 && cg_3[q50_k] == 1000005 { q50 = cg_h[q50_k]; } }
