var fault_rupture = fault_rupture_facts;

var sudden_energy_release = sudden_energy_release_facts;

var instances_earthquake = [].concat(
  // 0.6::eruption; 0.3::earthquake :- sudden_energy_release, fault_rupture(_A1).
  (function() {
    return _.flatten(map(function(e1) {
      return _.flatten(map(function(e2) {
        var _A1 = e2.t[0];
        var chosen = choose([0.6, 0.3]);
        return [
          ['eruption', [], and([e1.v, e2.v, chosen[0]])],
          ['earthquake', [], and([e1.v, e2.v, chosen[1]])]
        ];
      }, _.values(fault_rupture)));
    }, probe(sudden_energy_release, [])));
  })()
);
var earthquake = relation({}, only('earthquake', instances_earthquake));
var eruption = relation({}, only('eruption', instances_earthquake));

// component 0 bool
// component 1 bool
var model = function() {
  return [holds(eruption, [])(),
          holds(earthquake, [])()];
};
Infer({method: 'enumerate'}, model);

